const wrapper = $input.first().json;
// Wazuh integration POSTs the alert; n8n webhook wraps it under `body`
const raw = wrapper.body && wrapper.body.rule ? wrapper.body : wrapper;
const a = raw.agent || {};
const r = raw.rule || {};
const d = raw.data || {};
const al = d.alert || raw.alert || {};
const srcIp = d.srcip || al.src_ip || 'N/A';
const dstIp = d.dstip || al.dest_ip || 'N/A';
const dstPort = (d.dstport || al.dest_port || 'N/A').toString();
const sig = al.signature || raw.description || r.description || 'unknown';
const action = al.action || d.action || 'alerted';
return [{ json: {
  alert: raw,
  ruleId: String(r.id || ''),
  ruleLevel: r.level || 0,
  agentName: a.name || 'unknown',
  srcIp, dstIp, dstPort, sig, action,
  isCritical: (r.level || 0) >= 13
}}];

const item = $input.first().json;
const key = `${item.srcIp}_${item.ruleId}`;
const now = Date.now();

const staticData = $getWorkflowStaticData('global');
staticData.dedupe = staticData.dedupe || {};

const lastSeen = staticData.dedupe[key];
// Dedupe for 24 hours (86400000 ms)
if (lastSeen && (now - lastSeen < 86400000)) {
  return [];
}

staticData.dedupe[key] = now;
return [{ json: item }];
